% === Correlation Loss: Theory vs. Simulation ===
clc; clear; close all;

fprintf('Correlation Loss analysis: starting simulation ...\n'); %[output:85920ce7]

PRNID = 7;                          
f_chip = 1.023e6; T_int = 0.01; N_chips = f_chip * T_int;           

[~, L1Cp, L1Co] = gpsL1CCodes(PRNID);
pure_pilot_chips = (1 - 2*double(L1Cp)) .* (1 - 2*double(L1Co(1))); 

df_array = 1:10; % Duty Factor 1~10 테스트
loss_theory = zeros(length(df_array), 1);
loss_sim = zeros(length(df_array), 1);

slowFast = 0; zcount = 902044820;  
hexKey = '2B7E151628AED2A6ABF7158809CF4F3C'; secret_key = hexToBits(hexKey);
sector_pattern = get_sector_pattern();

for i = 1:length(df_array) %[output:group:31aed1a6]
    df = df_array(i);
    df_ratio = df / 33;
    
    loss_theory(i) = -20 * log10(1 - df_ratio);
    
    [marker_indices, marker_symbols] = marker_overlay_symbol( ...
        PRNID, slowFast, zcount, df, 0, secret_key, sector_pattern);
    
    tx_enh = pure_pilot_chips;
    tx_enh(marker_indices) = marker_symbols * -1; 
    
    corr_pure = abs(sum(pure_pilot_chips .* pure_pilot_chips));
    corr_enh  = abs(sum(tx_enh .* pure_pilot_chips));
    
    loss_sim(i) = -20 * log10(corr_enh / corr_pure);
     %[output:6ef0b972]
end %[output:group:31aed1a6]

figure('Name', 'Correlation Loss vs Duty Factor', 'Color', 'w', 'Position', [100, 150, 600, 450]); %[output:0f066ec0]
plot(df_array, loss_theory, '-k', 'LineWidth', 2); hold on; %[output:0f066ec0]
plot(df_array, loss_sim, 'bs', 'MarkerSize', 8, 'LineWidth', 1.5); %[output:0f066ec0]
grid on; %[output:0f066ec0]
xlabel('Duty Factor (Markers per 33-chip segment)', 'FontSize', 12, 'FontWeight', 'bold'); %[output:0f066ec0]
ylabel('Receiver Correlation Loss (dB)', 'FontSize', 12, 'FontWeight', 'bold'); %[output:0f066ec0]
title('Correlation Loss induced by Puncturing', 'FontSize', 13, 'FontWeight', 'bold'); %[output:0f066ec0]
legend('Theoretical Loss', 'Simulated Loss', 'Location', 'northwest'); %[output:0f066ec0]
set(gca, 'FontSize', 11); %[output:0f066ec0]

